/**
 * Silhouette anatomique issue des tracés exacts GymMane (body_svg.dart / body_svg_female.dart).
 * 14 muscles recto (gauche) et verso (droite), homme et femme, sélection ou carte de chaleur.
 */
import { useMemo, useState } from 'preact/hooks';
import { t } from './i18n.js';

// Ordre des muscles : identique à l'ordre des clés de muscleFills dans GymMane.
const MUSCLES = ['biceps', 'avant-bras', 'pectoraux', 'triceps', 'abdos', 'obliques', 'quadriceps', 'epaules', 'mollets', 'trapezes', 'dos', 'lombaires', 'ischios', 'fessiers'];
const CLE_GYMMANE = { biceps: 'biceps', 'avant-bras': 'forearm', pectoraux: 'chest', triceps: 'triceps', abdos: 'abdomen', obliques: 'obliques', quadriceps: 'quads', epaules: 'shoulders', mollets: 'calves', trapezes: 'trapezius', dos: 'back', lombaires: 'lowerback', ischios: 'hamstrings', fessiers: 'glutes' };
const FRONTIERE = BODY_VIEW_W / 2;

export const RAMPE_HEAT = {
  ember: ['#7A4028', '#B4632C', '#E38B3A', '#FFC168'],
  green: ['#1B4B2C', '#2C7A44', '#3FA95C', '#63D67F'],
  blue: ['#1E3A5C', '#2C5E96', '#3D86C9', '#6EB4F0'],
  mono: ['#3A3A3A', '#5E5E5E', '#8C8C8C', '#D8D8D8'],
};

const lite = 'color-mix(in srgb, var(--raised2) 86%, var(--text3))';
export const idle = 'color-mix(in srgb, var(--raised2) 68%, var(--text2))';

const art = (sexe) => (sexe === 'f' ? {
  base: FEMALE_BASE_MAIN, lite: FEMALE_BASE_LITE,
  fills: FEMALE_FILLS, hits: FEMALE_HITS,
  head: FEMALE_HEAD, headInner: FEMALE_HEAD_INNER, headCut: FEMALE_HEAD_CUT,
} : {
  base: MALE_BASE_MAIN, lite: MALE_BASE_LITE,
  fills: MALE_FILLS, hits: MALE_HITS,
  head: [], headInner: [], headCut: 0,
});

function couleurZone({ mode, ramp, selected, intensite }) {
  if (mode === 'heat') {
    const v = intensite ?? 0;
    const n = v <= 1 ? Math.min(4, Math.max(1, Math.ceil(v * 4))) : Math.min(4, Math.max(1, Math.round(v)));
    return v > 0 ? RAMPE_HEAT[ramp]?.[n - 1] ?? RAMPE_HEAT.ember[n - 1] : idle;
  }
  return selected ? 'var(--ember)' : idle;
}

function Paths({ d, id, onToggle, mode, classe }) {
  return d.map((p, i) => (
    <path
      key={`${id}-${i}`}
      d={p}
      fill={classe === 'sil-hit' ? 'transparent' : undefined}
      stroke="none"
      className={classe}
      onClick={onToggle ? () => onToggle(id) : undefined}
    />
  ));
}

function MuscleGroupe({ id, art, mode, ramp, selection, intensites, couleurs, onToggle, survol, setSurvol }) {
  const sel = selection instanceof Set ? selection : new Set(Array.isArray(selection) ? selection : selection ? [selection] : []);
  const actif = sel.has(id);
  const cliquable = Boolean(onToggle);
  const fill = couleurs?.[id] ?? couleurZone({ mode, ramp, selected: actif, intensite: intensites?.[id] ?? 0 });
  const cle = CLE_GYMMANE[id];
  const paths = art.fills[cle] ?? [];
  const hits = art.hits[cle] ?? [];
  return (
    <g
      id={`muscle-${id}`}
      className="sil-muscle"
      fill={fill}
      role={cliquable ? 'button' : undefined}
      tabIndex={cliquable ? 0 : undefined}
      aria-pressed={cliquable ? actif : undefined}
      aria-label={t.muscles[id] ?? id}
      style={{ cursor: cliquable ? 'pointer' : 'default' }}
      onClick={(e) => { if (cliquable && e.target === e.currentTarget) onToggle(id); }}
      onKeyDown={(e) => {
        if (!cliquable) return;
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onToggle(id); }
      }}
      onFocus={() => setSurvol?.(id)}
      onBlur={() => setSurvol?.(null)}
    >
      <Paths d={paths} id={id} onToggle={onToggle} mode={mode} classe="sil-zone" />
      {actif && mode !== 'selection' && paths.map((p, i) => <path key={`contour-${i}`} d={p} fill="none" stroke="var(--text)" stroke-width="2.5" stroke-linejoin="round" />)}
      {cliquable && mode === 'selection' && hits.length > 0 && <Paths d={hits} id={id} onToggle={onToggle} mode={mode} classe="sil-hit" />}
    </g>
  );
}

function CorpsSvg({ sexe, mode, ramp, selection, intensites, couleurs, onToggle, slice, labels }) {
  const a = art(sexe);
  const clip = a.headInner.length > 0;
  const clipId = `sil-clip-${sexe}-${slice || 'plein'}`;
  const vue = slice === 'back' ? `${FRONTIERE} 0 ${FRONTIERE} ${BODY_VIEW_H}` : slice === 'front' ? `0 0 ${FRONTIERE} ${BODY_VIEW_H}` : `0 0 ${BODY_VIEW_W} ${BODY_VIEW_H}`;
  return (
    <svg className="sil-corps" viewBox={vue} width="100%" role="group" aria-label={labels}>
      <defs>
        {clip && (
          <clipPath id={`${clipId}-corps`}>
            <rect x={-BODY_VIEW_W} y={a.headCut} width={BODY_VIEW_W * 3} height={BODY_VIEW_H * 2} />
          </clipPath>
        )}
        {clip && (
          <clipPath id={clipId}>
            <rect x={-BODY_VIEW_W} y={a.headCut} width={BODY_VIEW_W * 3} height={BODY_VIEW_H * 2} />
            {a.headInner.map((p, i) => <path key={i} d={p} />)}
          </clipPath>
        )}
      </defs>
      {/* paintBodyBase : corps coupé sous headCut, puis la tête par-dessus ; les muscles ensuite, coupés par clipMuscles. */}
      <g clip-path={clip ? `url(#${clipId}-corps)` : undefined}>
        {a.base.map((p, i) => <path key={`b${i}`} d={p} fill="var(--raised2)" stroke="none" />)}
        {a.lite.map((p, i) => <path key={`l${i}`} d={p} fill={lite} stroke="none" />)}
      </g>
      {a.head.map((p, i) => <path key={`h${i}`} d={p} fill={lite} stroke="none" />)}
      <g clip-path={clip ? `url(#${clipId})` : undefined}>
        {MUSCLES.map((id) => {
          if (!a.fills[CLE_GYMMANE[id]]) return null;
          return <MuscleGroupe key={id} id={id} art={a} mode={mode} ramp={ramp} selection={selection} intensites={intensites} couleurs={couleurs} onToggle={onToggle} />;
        })}
      </g>
    </svg>
  );
}

/**
 * @param {'selection'|'heat'} props.mode
 * @param {'front'|'back'|'both'} props.vueInitiale
 * @param {'m'|'f'} props.sexe
 * @param {Set|Array} props.selection
 * @param {(id: string) => void} props.onToggle
 * @param {Record<string, number>} props.intensites 0..1 (ou 1..4)
 * @param {'ember'|'green'|'blue'|'mono'} props.ramp
 */
export function SilhouetteSvg({ mode = 'selection', vueInitiale = 'both', sexe = 'm', selection = new Set(), onToggle, intensites = {}, couleurs, ramp = 'ember', lang = 'fr' }) {
  const vue = vueInitiale;
  const labels = useMemo(
    () =>
      lang === 'en'
        ? { avant: 'Front view muscle map', arriere: 'Back view muscle map', face: 'Front', dos: 'Back', cote: 'Side by side' }
        : { avant: 'Carte musculaire : face', arriere: 'Carte musculaire : dos', face: 'Face', dos: 'Dos', cote: 'Côte à côte' },
    [lang],
  );

  const slice = vueInitiale === 'both' ? (vue === 'front' ? 'front' : vue === 'back' ? 'back' : null) : (vueInitiale === 'back' ? 'back' : vueInitiale === 'front' ? 'front' : null);

  return (
    <div className={`silhouette-svg ${mode === 'selection' ? 'sil-selection' : ''}`}>
      <CorpsSvg sexe={sexe} mode={mode} ramp={ramp} selection={selection} intensites={intensites} couleurs={couleurs} onToggle={onToggle} slice={slice} labels={slice === 'back' ? labels.arriere : slice === 'front' ? labels.avant : labels.cote} />
    </div>
  );
}

// Figure d'un muscle autour du radar des progrès (muscle_radar.dart, MuscleFigurePainter) : moitié face ou dos du corps, cadrée
// sur le muscle (crop), le muscle en couleur d'accent et les autres estompés.
const VUE_DOS = new Set(['trapezes', 'dos', 'triceps', 'fessiers', 'ischios', 'mollets']);
const FUSION = { abdos: 'obliques', dos: 'lombaires' };
export function cadreFigure(id) {
  const cx = VUE_DOS.has(id) ? 411 : 115;
  const cadre = id === 'mollets' ? [cx - 100, 262, 200, 200] : [cx - 135, ['quadriceps', 'ischios', 'fessiers'].includes(id) ? 160 : -4, 270, 270];
  // Contenu : le cadre limité à la moitié du corps (la démo mesure les tracés, l'écart reste sous quelques pixels).
  const [mx0, mx1] = VUE_DOS.has(id) ? [270, 540] : [0, 262];
  const l = Math.max(cadre[0], mx0), r = Math.min(cadre[0] + cadre[2], mx1), t0 = Math.max(cadre[1], 0), b = Math.min(cadre[1] + cadre[3], BODY_VIEW_H);
  return { cadre, contenu: [l, t0, r - l, b - t0], moitie: [mx0, 0, mx1 - mx0, BODY_VIEW_H] };
}
export function FigureMuscle({ id, x, y, taille }) {
  const a = art('m');
  const { cadre, moitie } = cadreFigure(id);
  const allumes = new Set([CLE_GYMMANE[id], CLE_GYMMANE[FUSION[id]]]);
  const clip = `fig-clip-${id}`;
  return <svg class="fig-muscle" x={x} y={y} width={taille} height={taille} viewBox={cadre.join(' ')} aria-hidden="true">
    <defs><clipPath id={clip}><rect x={moitie[0]} y={moitie[1]} width={moitie[2]} height={moitie[3]} /></clipPath></defs>
    <g clip-path={`url(#${clip})`}>
      {[...a.base, ...a.lite, ...a.head].map((p, i) => <path key={`b${i}`} d={p} class="fig-peau" />)}
      {Object.entries(a.fills).flatMap(([cle, ds]) => ds.map((p, i) => <path key={`${cle}${i}`} d={p} class={allumes.has(cle) ? 'fig-on' : 'fig-reste'} />))}
    </g>
  </svg>;
}

// Corps de l'étape « corps » de l'onboarding (onboarding_screen.dart, BodyPainter) : vue de face seule
// (Rect.fromLTRB(-4, -2, 234, 466)), tous les muscles à 78 % entre le fond relevé et l'accent.
export function CorpsOnboarding({ sexe = 'm' }) {
  const a = art(sexe);
  const clipId = `onb-clip-${sexe}`;
  const muscle = 'color-mix(in srgb, var(--accent) 78%, var(--raised2))';
  return <svg class="onb-corps-svg" viewBox="-4 -2 238 468" aria-hidden="true">
    {a.headInner.length > 0 && <defs><clipPath id={clipId}><rect x={-BODY_VIEW_W} y={a.headCut} width={BODY_VIEW_W * 2} height={BODY_VIEW_H * 2} />{a.headInner.map((p, i) => <path key={i} d={p} />)}</clipPath></defs>}
    <g clip-path={a.headInner.length > 0 ? `url(#${clipId})` : undefined}>
      {a.base.map((p, i) => <path key={`b${i}`} d={p} fill="var(--raised2)" />)}
      {a.lite.map((p, i) => <path key={`l${i}`} d={p} fill={lite} />)}
    </g>
    <g fill={muscle}>{Object.values(a.fills).flatMap((ds, k) => ds.map((p, i) => <path key={`${k}-${i}`} d={p} />))}</g>
    {a.head.map((p, i) => <path key={`h${i}`} d={p} fill={lite} />)}
  </svg>;
}
